function showSettings(){openPanel('按你舒服的方式',`${(db.profiles.archivedBabies||[]).map(b=>`<button class="choice" data-action="restore-baby" data-id="${esc(b.id)}">${babyAvatar(b)}<span>恢复 ${esc(b.name)}<small>已移除的宝宝</small></span>${icon('arrow-right')}</button>`).join('')}<button class="choice" data-action="load-demo">${icon('chart')}<span>两周示例数据<small>独立示例宝宝，不覆盖你的记录</small></span>${icon('chevron-right')}</button><label class="setting-row"><span>减少动态效果<small>保留文字状态提示，减少界面位移动效</small></span><input type="checkbox" id="reduce-motion" ${db.prefs.reduced?'checked':''}></label><div class="actions"><button class="secondary" data-action="export">导出本机备份</button><button class="secondary" data-action="import">恢复备份</button></div><input type="file" id="import-file" accept="application/json,.json" hidden><p class="foot-note">恢复时按记录 ID 合并，不覆盖同 ID 的现有记录。</p><div class="source-line"><strong>数据与功能说明</strong><p class="foot-note">对话使用本地规则与示例回复，没有连接真实 AI。不会上传照片、录音或记录；浏览器的语音识别服务可能由浏览器厂商处理。已发送附件仅保留当前会话预览，刷新后清除；分析服务和账号登录服务尚未接入。这里不提供医学诊断。</p></div><details class="debug"><summary>交互验证面板</summary><p>仅记录事件编号、状态和时间，不含输入内容。</p><div class="actions"><button class="secondary" data-action="demo-voice">语音流程演示</button><button class="secondary" data-action="demo-parse-fail">下次演示解析失败</button><button class="secondary" data-action="fail-next">下次保存失败</button><button class="secondary" data-action="delay-next">下次延迟</button><button class="quiet" data-action="reset-events">清空事件</button></div><pre id="event-log"></pre></details><div class="settings-reset"><button class="choice" data-action="confirm-reset-onboarding">${icon('arrow-right')}<span>重置首次引导<small>重新体验完整进入流程，保留宝宝和记录</small></span>${icon('chevron-right')}</button></div>`);trace('T-settings','shown')}
