function setMode(m){invalidateVoice();mode=m;$('#voice-button').hidden=m!=='voice';$('#chat-form').hidden=m!=='text';$('#mode-button').innerHTML=icon(m==='voice'?'edit':'mic');$('#mode-button').setAttribute('aria-label',m==='voice'?'切换到文字输入':'切换到按住说话');$('#voice-hint').hidden=true;if(m==='text')$('#chat-input').focus();announce(m==='text'?'已切换到文字输入':'已切换到按住说话');trace('T-input',m)}
function voiceHint(s){$('#voice-hint').hidden=false;$('#voice-hint').textContent=s;announce(s)}
function startVoice(){if(voiceHeld||busy||$('#panel').open)return;const API=window.SpeechRecognition||window.webkitSpeechRecognition;if(!API){setMode('text');voiceHint('当前浏览器不支持语音转文字，请直接输入。');companion('unavailable','可以打字告诉我');trace('T-voice','unsupported');return}voiceHeld=true;voiceFinal='';voiceStarted=Date.now();const session=++voiceSession;recognition=new API();recognition.lang='zh-CN';recognition.interimResults=true;recognition.continuous=true;$('#voice-button').classList.add('recording');$('#voice-button span').textContent='正在听… 松开结束';$('#voice-button small').textContent='上滑取消';voiceHint('正在申请麦克风。语音识别由浏览器提供。');companion('listening','我在听');recognition.onstart=()=>{if(session!==voiceSession)return;if(!voiceHeld){recognition.stop();return}voiceHint('正在听，松开后会先显示文字供你确认。');trace('T-voice','listening')};recognition.onresult=e=>{if(session!==voiceSession)return;voiceFinal=Array.from(e.results).map(r=>r[0].transcript).join('');voiceHint(voiceFinal||'正在听…')};recognition.onerror=e=>{if(session!==voiceSession)return;voiceSession++;voiceHeld=false;resetVoice();voiceHint(e.error==='not-allowed'?'麦克风没有获准使用，可以切换文字输入。':'没有识别成功，请重试或切换文字输入。');companion('error','可以再试一次');trace('T-voice','failed')};recognition.onend=()=>{if(session!==voiceSession)return;voiceHeld=false;resetVoice();if(voiceFinal.trim()){openPanel('这是你刚刚说的吗？',`<p class="panel-copy">文字还没有发送。你可以改一改，再交给我整理。</p><form id="voice-review"><label class="field">识别文字<textarea name="transcript" rows="4" required maxlength="1000">${esc(voiceFinal)}</textarea></label><button class="primary full" type="submit">确认发送</button></form>`);trace('T-voice','review')}else voiceHint('没有听清。这次没有发送，可以再试一次。')};try{recognition.start();voiceTimeout=setTimeout(()=>endVoice(false),30000)}catch(e){voiceHeld=false;resetVoice();voiceHint('语音暂时不可用，请切换文字输入。')}}
function invalidateVoice(){voiceSession++;voiceHeld=false;if(recognition){recognition.abort();recognition=null}resetVoice()}
function resetVoice(){clearTimeout(voiceTimeout);$('#voice-button').classList.remove('recording');$('#voice-button span').textContent='按住说话';$('#voice-button small').textContent='松开后先确认'}
function endVoice(cancel=false){if(!voiceHeld)return;voiceHeld=false;if(cancel){voiceSession++;recognition?.abort();voiceFinal='';resetVoice();voiceHint('这段语音已取消，没有发送。');companion('ready','已取消');trace('T-voice','cancelled')}else{recognition?.stop();resetVoice();voiceHint('正在整理识别文字…');companion('processing','正在整理识别文字')}}
