function showCry(origin){const back=origin?.closest?.('.floating-tools')?()=>{closePanel();goHome()}:showMore;openPanel('听哭闹',`<div class="audio-capture" id="audio-capture" data-state="ready"><div class="recording-orbit"><canvas id="cry-companion" width="120" height="112" data-companion="ready" aria-label="助手准备录音"></canvas><span class="recording-state-icon">${icon('mic')}</span><strong id="record-seconds">00:00</strong></div>${waveBars()}<progress id="record-progress" max="30" value="0" aria-label="录音时长，最多30秒"></progress><p id="cry-state" role="status">准备好后，录一段宝宝的声音</p><small id="record-duration-hint">10 秒后变绿 · 最多 30 秒</small></div><div id="cry-preview"></div><div class="actions"><button class="secondary" data-action="start-cry">${icon('mic')}开始录音</button><button class="secondary" data-action="stop-cry" hidden>${icon('stop')}结束录音</button><button class="primary" data-action="send-media" disabled>${icon('sparkles')}发送并分析</button></div>`,back);Companion.refresh();}
function setCryCompanion(state,glyph){const c=$('#cry-companion');if(!c)return;c.dataset.companion=state;const badge=$('.recording-state-icon');if(badge)badge.innerHTML=icon(glyph||({ready:'mic',confirm:'pause',listening:'waveform',error:'alert'})[state]||'mic');Companion.refresh();}
function updateRecording(){const seconds=Math.min(30,(Date.now()-recordStart)/1000);const card=$('#audio-capture');if(!card)return;card.dataset.state=seconds>10?'ready-length':'recording';card.dataset.enough=String(seconds>=10);card.style.setProperty('--record-fill','hsl('+ (46+Math.min(seconds/10,1)*116)+' 64% 87%)');$('#record-seconds').textContent='00:'+String(Math.floor(seconds)).padStart(2,'0');$('#record-progress').value=seconds;$('#record-duration-hint').textContent=seconds>10?'已超过 10 秒，可以结束录音':'10 秒后变绿 · 最多 30 秒';}
