function swipeStart(x,y,target,id){const bounds=$('#app').getBoundingClientRect();if($('#panel').open||target.closest('button,input,textarea,select,a,.composer-area,.chart-scroll')||x<=bounds.left+24||x>=bounds.right-24)return;swipe={x,y,id};}
function swipeEnd(x,y){if(!swipe)return;const {x:sx,y:sy}=swipe;swipe=null;if($('#panel').open)return;const dx=x-sx,dy=y-sy;if(Math.abs(dx)<72||Math.abs(dx)<Math.abs(dy)*1.6||Math.abs(dy)>65)return;suppressSwipeClickUntil=performance.now()+180;getSelection()?.removeAllRanges();if(activeRoute!=='home')goHome();else if(dx>0)showTrends();else{recordDay=today();showRecords()}}
