function addSchemaField(){if($('#schema-fields').children.length>=6){toast('每个模板最多 6 个字段');return}const row=document.createElement('div');row.className='schema-row';row.innerHTML=`<label class="field">字段名称<input data-field="label" required maxlength="30" placeholder="例如：时长"></label><div class="field-pair"><label class="field">类型<select data-field="kind"><option>文字</option><option>数字</option><option>选择</option></select></label><label class="field">单位（可选）<input data-field="unit" maxlength="12" placeholder="分钟"></label></div><label class="check-row"><input data-field="required" type="checkbox" checked>必填</label><div class="field-pair"><label class="field">数字最小值<input data-field="min" type="number" value="0"></label><label class="field">数字最大值<input data-field="max" type="number" value="10000"></label></div><label class="field">选项（选择类型必填）<input data-field="options" placeholder="公园，室内，其他" maxlength="100"></label><button type="button" class="quiet" data-action="schema-remove">移除此字段</button>`;$('#schema-fields').append(row);trace('T-schema','field-added')}
